mapper.insert:
INSERT INTO weekly_plan (
    user_id, plan_scope, name, status, week_start, timezone, profile_version_no, calorie_low, calorie_high,
    rules_version, validation_level, validation_json, note, source_session_id, current_version,
    generation_source, generation_metadata_json, created_at, updated_at
) VALUES (
    #{userId}, #{planScope}, #{name}, #{status}, #{weekStart}, #{timezone}, #{profileVersionNo}, #{calorieLow}, #{calorieHigh},
    #{rulesVersion}, #{validationLevel}, #{validationJson}, #{note}, #{sourceSessionId}, #{currentVersion},
    #{generationSource}, #{generationMetadataJson}, #{createdAt}, #{updatedAt}
)

INSERT INTO weekly_plan_version (
    plan_id, plan_scope, version_no, profile_version_no, profile_snapshot_json,
    rules_version, source_session_id, fact_sources_json, resource_snapshot_json,
    validation_json, created_at
) VALUES (
    #{planId}, #{planScope}, #{versionNo}, #{profileVersionNo}, #{profileSnapshotJson},
    #{rulesVersion}, #{sourceSessionId}, #{factSourcesJson}, #{resourceSnapshotJson},
    #{validationJson}, #{createdAt}
)

INSERT INTO weekly_plan_item (
    plan_id, version_no, resource_type, resource_id, name, local_date,
    start_time, end_time, note, plan_params_json, created_at, updated_at
) VALUES (
    #{planId}, #{versionNo}, #{resourceType}, #{resourceId}, #{name}, #{localDate},
    #{startTime}, #{endTime}, #{note}, #{planParamsJson}, #{createdAt}, #{updatedAt}
)
